   seq('رتّب درس الأستاذة هند', [('teacher', 'النداء: عزيزي وعزيزتي'), ('student', 'التمنّي: أرجو أن + مضارع'), ('pen', 'الأمر والنهي: أرسلي ولا تنسَي'), ('calendar', 'الزمن: مضى وما زال')]),
